        int[] returnedLeaves = {4, 0, 3, 1};   // range 0..4, one missing
        log.info("Rajesh returned booklet leaves: " + Arrays.toString(returnedLeaves));

        ChequeLeafAuditor auditor = new ChequeLeafAuditor();
