package com.bank.cheque;

public class ChequeLeafAuditor {

    public int findMissingLeaf(int[] leaves) {
        int i = 0, n = leaves.length;
        // Cyclic placement: value v belongs at index v; ignore value == n.
        while (i < n) {
            int target = leaves[i];
            if (target < n && leaves[i] != leaves[target]) {
                int tmp = leaves[i]; leaves[i] = leaves[target]; leaves[target] = tmp;
            } else {
                i++;
            }
        }
        // First index whose value is wrong is the missing number.
        for (int idx = 0; idx < n; idx++) {
            if (leaves[idx] != idx) return idx;
        }
        return n;   // all 0..n-1 present means n is missing
    }
}
